INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Hat jeder hier nur einen Vorgesetzten?', 2, '[{"text": "Nein", "correct": true, "because": "Fach- und Projektleitung"}, {"text": "Ja", "correct": false, "because": "Duale Verantwortung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal beschreibt diese Struktur am besten?', 3, '[{"text": "Doppelte Weisungslinie", "correct": true, "because": "Fachlich und projektbezogen"}, {"text": "Einheitliche Hierarchie", "correct": false, "because": "Zwei Dimensionen"}, {"text": "Flache Struktur", "correct": false, "because": "Komplexer Aufbau"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt mir diese Organisation?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Projektanpassung möglich"}, {"text": "Nutzung von Expertise", "correct": true, "because": "Fachwissen integriert"}, {"text": "Schnelle Befehle", "correct": false, "because": "Abstimmung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es gibt zwei Chefs. b) Prioritäten sind immer klar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prioritäten oft unklar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit in dieser Struktur?', 4, '[{"text": "Projektziele", "correct": false, "because": "Eine Hauptaufgabe"}, {"text": "Fachliche Anforderungen", "correct": false, "because": "Zweite Dimension"}, {"text": "Einzelentscheidungen", "correct": true, "because": "Abstimmung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob diese Struktur für einfache Projekte passt?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexität oft überflüssig"}, {"text": "Ja", "correct": false, "because": "Besser für Komplexes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderung sehe ich hier oft?', 3, '[{"text": "Konflikte zwischen Linien", "correct": true, "because": "Unterschiedliche Ziele"}, {"text": "Zu wenig Verantwortung", "correct": false, "because": "Eher zu viel"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Koordination nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente prägen diese Organisation?', 5, '[{"text": "Projektleitung", "correct": true, "because": "Zielorientiert"}, {"text": "Fachliche Leitung", "correct": true, "because": "Expertenwissen"}, {"text": "Einheitliche Weisung", "correct": false, "because": "Duale Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Matrix ist flexibel. b) Sie ist immer chaotisch. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Chaos nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Klare Kommunikation", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "Koordination", "correct": false, "because": "Schlüssel zum Erfolg"}, {"text": "Einzelne Befehlskette", "correct": true, "because": "Duale Linien üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist diese Struktur immer effizient?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Koordination"}, {"text": "Ja", "correct": false, "because": "Komplexität kann bremsen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördern den Erfolg in dieser Struktur?', 4, '[{"text": "Klare Rollen", "correct": true, "because": "Reduziert Verwirrung"}, {"text": "Abstimmung", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Schnellschüsse", "correct": false, "because": "Koordination nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hier jeder alles entscheidet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Weisungen sind spezifisch"}, {"text": "Ja", "correct": false, "because": "Rollen getrennt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in dieser Organisation?', 3, '[{"text": "Zielabstimmung", "correct": true, "because": "Vermeidet Widersprüche"}, {"text": "Schnelle Befehle", "correct": false, "because": "Koordination nötig"}, {"text": "Einzelinitiative", "correct": false, "because": "Teamarbeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es gibt Projekt- und Fachchefs. b) Entscheidungen sind immer schnell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entscheidungen oft komplex"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile könnten auftreten?', 5, '[{"text": "Unklare Prioritäten", "correct": true, "because": "Duale Weisungen"}, {"text": "Langsame Prozesse", "correct": true, "because": "Abstimmung nötig"}, {"text": "Hohe Autonomie", "correct": false, "because": "Eher eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Projektziele", "correct": false, "because": "Kern der Struktur"}, {"text": "Fachwissen", "correct": false, "because": "Entscheidend für Erfolg"}, {"text": "Einheitliche Linie", "correct": true, "because": "Matrix ist dual"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert diese Struktur klare Verantwortung?', 3, '[{"text": "Nein", "correct": true, "because": "Rollen können verschwimmen"}, {"text": "Ja", "correct": false, "because": "Duale Linien komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob diese Struktur für große Projekte geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Komplexität beherrschbar"}, {"text": "Nein", "correct": false, "because": "Ideal für Komplexes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle wähle ich für Projektziele?', 4, '[{"text": "Projektmanager", "correct": true, "because": "Fokus auf Projekt"}, {"text": "Fachleiter allein", "correct": false, "because": "Nur fachlich"}, {"text": "Teammitglied", "correct": false, "because": "Weisung nötig"}]');
